import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"対応ファイルマネージャーとダイアログ統合","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 3 つの主要な統合機能","slug":"_1-3-つの主要な統合機能","link":"#_1-3-つの主要な統合機能","children":[]},{"level":2,"title":"2. Windows 標準コンポーネント（組み込み・設定不要）","slug":"_2-windows-標準コンポーネント-組み込み・設定不要","link":"#_2-windows-標準コンポーネント-組み込み・設定不要","children":[]},{"level":2,"title":"3. サードパーティ製ファイラー対応（プラグイン）","slug":"_3-サードパーティ製ファイラー対応-プラグイン","link":"#_3-サードパーティ製ファイラー対応-プラグイン","children":[{"level":3,"title":"Directory Opus 向けの統合","slug":"directory-opus-向けの統合","link":"#directory-opus-向けの統合","children":[]},{"level":3,"title":"Everything 互換サービス (IPC)","slug":"everything-互換サービス-ipc","link":"#everything-互換サービス-ipc","children":[]}]},{"level":2,"title":"4. 各種アプリの独自ダイアログ対応（専用プラグイン）","slug":"_4-各種アプリの独自ダイアログ対応-専用プラグイン","link":"#_4-各種アプリの独自ダイアログ対応-専用プラグイン","children":[]}],"relativePath":"ja-JP/user-guide/file-manager-support.md","filePath":"ja-JP/user-guide/file-manager-support.md","lastUpdated":1791112464000}`),a={name:`ja-JP/user-guide/file-manager-support.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="対応ファイルマネージャーとダイアログ統合" tabindex="-1">対応ファイルマネージャーとダイアログ統合 <a class="header-anchor" href="#対応ファイルマネージャーとダイアログ統合" aria-label="Permalink to “対応ファイルマネージャーとダイアログ統合”">​</a></h1><p>Lertaro は単体のデスクトップランチャーとしても、Windows エクスプローラー、サードパーティ製ファイラー、各種アプリのダイアログに組み込まれた状態としても使え、ファイルを開く・保存する・フォルダーを移動する作業を効率化します。</p><h2 id="_1-3-つの主要な統合機能" tabindex="-1">1. 3 つの主要な統合機能 <a class="header-anchor" href="#_1-3-つの主要な統合機能" aria-label="Permalink to “1. 3 つの主要な統合機能”">​</a></h2><p>対象となるウィンドウの特性に応じて、最大 3 つの統合機能が提供されます。</p><ul><li><strong>インライン検索（Inline Search）</strong>：対象ウィンドウの上部やダイアログ内に検索バーを直接埋め込み、作業中の画面を離れることなく現在のフォルダーや全体を即座に検索。対応するファイル一覧で英数字を入力した瞬間に現れ、最初に入力した 1 文字を自身のボックスへ引き継ぎます。</li><li><strong>クイックナビゲーション（Quick Navigation）</strong>：余白の中クリック（有効にした場合のみ左ダブルクリック。<strong>既定でオフ</strong>）やロゴのクリックで、現在開いているフォルダー、お気に入り、履歴、カスタム分類を含む階層メニューを表示。サードパーティ製ファイラーは中クリックのみに対応しています。</li><li><strong>アクティブパス検知（Active Path Detection）</strong>：対象ウィンドウが現在開いているフォルダーをリアルタイムに検知し、検索範囲を自動的にそのフォルダーに限定したり、相対パス操作を正確に解決。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>ファイルダイアログにドッキングしたインラインウィンドウは、意図的に<strong>キーボードをダイアログ側に残します</strong>。これまでどおりそのまま入力を続けられるためです。<code>Ctrl</code> の 2 回連打（または設定済みの呼び出しホットキー）でキャレットをウィンドウへ移し、検索語が空のウィンドウでもう一度押すとフォーカスをダイアログへ返せます。詳しくは <a href="./hotkeys.html"><strong>ホットキー</strong></a> の「インラインウィンドウの呼び出しとフォーカスの引き継ぎ」を参照してください。</p></div><h2 id="_2-windows-標準コンポーネント-組み込み・設定不要" tabindex="-1">2. Windows 標準コンポーネント（組み込み・設定不要） <a class="header-anchor" href="#_2-windows-標準コンポーネント-組み込み・設定不要" aria-label="Permalink to “2. Windows 標準コンポーネント（組み込み・設定不要）”">​</a></h2><p>以下の標準コンポーネントは、追加のプラグインなしで標準でサポートされています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">対象ウィンドウ</th><th style="text-align:left;">インライン検索</th><th style="text-align:left;">クイックナビゲーション操作</th><th style="text-align:left;">アクティブパス検知</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows エクスプローラー</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">余白部分で中クリック、または有効化すれば左ダブルクリック</td><td style="text-align:left;">対応</td></tr><tr><td style="text-align:left;"><strong>モダン「開く/保存」ダイアログ</strong></td><td style="text-align:left;">対応（ダイアログ内に直接埋め込み）</td><td style="text-align:left;">中クリック、またはロゴアイコンを左クリック</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>クラシック「開く/保存」ダイアログ</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンを左クリック</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>フォルダーの参照ダイアログ</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンを左クリック</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>各種ファイル選択ダイアログでは、Lertaro がダイアログ内部に直接埋め込まれているため、外部からのパス検知は不要です。クイックナビゲーションで項目を選択すると、ダイアログがそのフォルダーへ直接移動します。</p></div><h2 id="_3-サードパーティ製ファイラー対応-プラグイン" tabindex="-1">3. サードパーティ製ファイラー対応（プラグイン） <a class="header-anchor" href="#_3-サードパーティ製ファイラー対応-プラグイン" aria-label="Permalink to “3. サードパーティ製ファイラー対応（プラグイン）”">​</a></h2><p>高度なファイラーをご利用の方向けに、専用の統合プラグインが用意されています。<a href="./settings/plugins.html"><strong>設定 → プラグイン</strong></a> で有効化し、インライン検索やクイックナビゲーションを個別に設定できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">ファイラー名</th><th style="text-align:left;">インライン検索</th><th style="text-align:left;">クイックナビゲーション操作</th><th style="text-align:left;">アクティブパス検知</th><th style="text-align:left;">通信方式・プロトコル</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;"><code>WM_COPYDATA</code> 公式リモート API</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;"><code>WM_COPYDATA</code> 公式メッセージプロトコル</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;">専用プロセス間通信</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;">Windows UI Automation</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">対応</td><td style="text-align:left;">ファイル一覧領域で中クリック</td><td style="text-align:left;">対応</td><td style="text-align:left;">Windows UI Automation</td></tr></tbody></table><h3 id="directory-opus-向けの統合" tabindex="-1">Directory Opus 向けの統合 <a class="header-anchor" href="#directory-opus-向けの統合" aria-label="Permalink to “Directory Opus 向けの統合”">​</a></h3><ul><li><strong>フォルダーサイズ列（Lertaro サイズ）</strong>：Directory Opus プラグインで「Lertaro サイズ列を有効化」にすると、カスタムスクリプト列が追加されます。Lertaro のインメモリインデックスから再帰的な合計サイズを直接取得するため、<strong>ディスク I/O ゼロ</strong> でドライブ全体のフォルダーサイズを表示できます。</li><li><strong>設定の保存</strong>：列セレクターで「Lertaro サイズ」を追加後、<strong>フォルダー → フォルダー形式 → 保存 → すべてのフォルダーに形式を保存</strong> をクリックして永続化します。</li></ul><h3 id="everything-互換サービス-ipc" tabindex="-1">Everything 互換サービス (IPC) <a class="header-anchor" href="#everything-互換サービス-ipc" aria-label="Permalink to “Everything 互換サービス (IPC)”">​</a></h3><p><a href="./settings/general.html#_1-システム-system"><strong>設定 → 一般 → システム</strong></a> で <strong>Everything 互換サービス (IPC) を有効化</strong> すると、標準の Everything Win32 IPC インターフェースをエミュレートします。Directory Opus、Total Commander、Flow Launcher などのツールから、Everything を起動することなく Lertaro のインメモリインデックスを直接利用できます。</p><h2 id="_4-各種アプリの独自ダイアログ対応-専用プラグイン" tabindex="-1">4. 各種アプリの独自ダイアログ対応（専用プラグイン） <a class="header-anchor" href="#_4-各種アプリの独自ダイアログ対応-専用プラグイン" aria-label="Permalink to “4. 各種アプリの独自ダイアログ対応（専用プラグイン）”">​</a></h2><p>標準の Windows ダイアログを使用せず、独自のカスタムダイアログを持つ主要アプリに対しても専用プラグインを提供しています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">アプリとダイアログ種別</th><th style="text-align:left;">インライン検索</th><th style="text-align:left;">クイックナビゲーション操作</th><th style="text-align:left;">備考</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> 開く/保存ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">WPS Writer、Spreadsheets、Presentation、PDF を網羅</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> 解凍ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">解凍先フォルダーを素早く指定</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 解凍ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">解凍先の出力フォルダーを即座に指定</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> ファイル追加ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">アーカイブに追加するファイルを素早く選択</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> 開く/保存ダイアログ</td><td style="text-align:left;">対応</td><td style="text-align:left;">中クリック、またはロゴアイコンをクリック</td><td style="text-align:left;">設計図面ファイルの素早い保管と呼び出しに最適化</td></tr></tbody></table><p>各プラグインはウィンドウの内部コントロール構造とハンドル階層を直接認識して動作するため、言語パックや細かな UI の違いに左右されません。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};